UPDATE public.srd_class_level_features SET summary='Trapfinding: o teste de Procurar informa que o Ladino pode localizar armadilhas com CD acima de 20, inclusive mágicas (CD 25 + nível da magia), e Operar Mecanismo informa a possibilidade de desarmar armadilhas mágicas. A definição da CD e a adjudicação do Mestre continuam no fluxo de perícias; flanqueamento do Ataque Furtivo segue pendente.', mechanics=mechanics||jsonb_build_object('engine_status','partial','implemented_features',jsonb_build_array('trapfinding_search_dc_over_20','trapfinding_magic_search_dc_formula','trapfinding_magic_disable_guidance','rogue_class_level_gate'),'pending_features',jsonb_build_array('trapfinding_automated_trap_resolution','sneak_attack_flanking')) WHERE class_id='ladino' AND class_level=1;